import { fileURLToPath } from 'node:url'
import { drizzle, type NodePgDatabase } from 'drizzle-orm/node-postgres'
import { migrate } from 'drizzle-orm/node-postgres/migrator'
import { Pool } from 'pg'
import * as schema from './schema/index.js'

export type Database = NodePgDatabase<typeof schema>
/** Either the root database handle or a transaction (`db.transaction(async (tx) => ...)`). */
export type DbExecutor = Pick<
  Database,
  'select' | 'insert' | 'update' | 'delete' | 'execute' | 'query'
>

/** SQL migrations generated by drizzle-kit, resolved from both `src/` (tests) and `dist/` (runtime). */
export const MIGRATIONS_FOLDER = fileURLToPath(
  new URL('../../drizzle', import.meta.url),
)

export function createPool(connectionString: string, max = 10): Pool {
  return new Pool({ connectionString, max })
}

export function createDatabase(pool: Pool): Database {
  return drizzle({ client: pool, schema, casing: 'snake_case' })
}

export async function runMigrations(connectionString: string): Promise<void> {
  const pool = createPool(connectionString, 1)
  try {
    await migrate(createDatabase(pool), {
      migrationsFolder: MIGRATIONS_FOLDER,
    })
  } finally {
    await pool.end()
  }
}
